// Framework-free: the function takes the node and returns the cleanup. Svelte: call it from an action or an effect; React: call it in an effect.
import { focusables } from "./focusable";

/** Tab/Shift+Tab cycle inside `node`; on cleanup focus returns to the element focused before. */
export function trapFocus(node: HTMLElement): () => void {
  const previous = document.activeElement as HTMLElement | null;
  if (!node.contains(previous)) queueMicrotask(() => focusables(node)[0]?.focus());
  const onKey = (e: KeyboardEvent) => {
    if (e.key !== "Tab") return;
    const items = focusables(node);
    if (!items.length) { e.preventDefault(); return; }
    const first = items[0], last = items[items.length - 1], cur = document.activeElement;
    if (e.shiftKey && (cur === first || !node.contains(cur))) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && (cur === last || !node.contains(cur))) { e.preventDefault(); first.focus(); }
  };
  node.addEventListener("keydown", onKey);
  return () => { node.removeEventListener("keydown", onKey); /* after the page is no longer inert */ requestAnimationFrame(() => { if (previous?.isConnected) previous.focus(); }); };
}

